import"./chunk-2NFLSA4Y.js";var s={centerOfMass:{theory:{concept:"[[The centre of mass is the point at which the whole mass of a body can be considered concentrated; in a uniform gravitational field the force of gravity acts on the body at this point.]] A body standing on a support stays in balance as long as its centre of mass is above the support; once the centre of mass moves beyond the edge, gravity turns the body and it tips over. The lower the centre of mass and the wider the support, the more stable the body."},section:{definition:{title:"What is the centre of mass?",text:"[[The centre of mass is the average position of all the mass of an object, where heavier parts count more.]] For a ruler it is the middle; for a hammer it is close to the heavy head. Gravity pulls on every part of an object, but the result is the same as if the whole weight acted at the centre of mass \u2014 which is why you can balance a ruler on one finger right under it."},finding:{title:"Finding it",text:"For several masses along a line, the centre of mass is the mass-weighted average of their positions: x_cm = (m\u2081x\u2081 + m\u2082x\u2082 + \u2026) / (m\u2081 + m\u2082 + \u2026). Two equal masses: exactly halfway between them. A mass twice as heavy pulls the centre twice as close to itself. The board has mass too: it counts as a mass at its middle."},support:{title:"Stable or not?",text:"[[An object resting on a support is stable while the vertical line through its centre of mass \u2014 the dashed plumb line \u2014 passes through the support.]] Here the support is w wide, so the board stays put while |x_cm| \u2264 w/2. A wider support allows more freedom: that is why we stand with our feet apart on a moving bus."},tipping:{title:"Why it tips",text:"When the centre of mass moves beyond the edge of the support, the weight has a lever arm d about that edge and makes a turning effect, a torque \u03C4 = M\xB7g\xB7d. Nothing on the other side can balance it, so the board turns about the edge and falls. The further beyond the edge, the faster it starts to tip."},low:{title:"Low and wide is stable",text:"Racing cars are built low and wide, buses carry their luggage under the floor, and tightrope walkers hold long poles \u2014 all to keep the centre of mass low and well above their support. The Leaning Tower of Pisa leans about 4\xB0, yet stands because its centre of mass is still above its base; engineers reduced the lean in the 1990s and 2000s to keep it that way."},everyday:{title:"Centre of mass in everyday life",text:"When you carry a heavy bag in one hand, you lean the other way to keep your centre of mass above your feet. A tall wardrobe with the heavy things on the top shelf tips over easily. Cranes carry heavy counterweights on the short arm so that the centre of mass stays above their base while they lift loads."},check:{title:"Check your understanding",text:"Masses of 20 kg at \u22120.6 m and 20 kg at +0.6 m: where is the centre of mass? (At 0.) A 30 kg mass at 0 and a 10 kg mass at 2 m, no board? (At 0.5 m.) The support is 1 m wide. Is x_cm = 0.6 m stable? (No \u2014 it is beyond 0.5 m.) How can a heavy board keep an overhanging load from tipping? (Its weight pulls the centre of mass back over the support.) Test each answer in the simulation."}},formula:{center:"Centre of mass: the mass-weighted average position",stability:"Stable while the centre of mass is above the support",torque:"Turning effect of the weight about the edge (d: distance beyond the edge)",rotation:"Rotation about the edge (I: moment of inertia)"},variable:{center:"Position of the centre of mass",mass:"Mass",width:"Width of the support",arm:"Distance of the centre of mass beyond the edge",torque:"Torque (turning effect)"},assumption:{pointMasses:"The loads are treated as points on the board.",rigid:"The board is rigid, thin and uniform; its own mass counts as a mass at its middle.",pivot:"When it tips, the board turns about the support edge without slipping or friction and stops when it reaches the ground."},param:{mass1:"Mass 1",mass2:"Mass 2",position1:"Position of mass 1",position2:"Position of mass 2",supportWidth:"Width of the support",plankMass:"Mass of the board",gravity:"Gravity",timeStep:"Time step"},hint:{mass:"A heavier mass pulls the centre of mass towards itself.",position:"Distance from the middle of the board: negative to the left, positive to the right.",supportWidth:"The centre of mass must stay above the support for the board to stay put.",plankMass:"The board's own mass counts as a mass at its middle."},measure:{center:"Centre of mass",supportMargin:"Distance to the edge (negative: tipping)",totalMass:"Total mass",angle:"Tilt of the board",loadsCenter:"Centre of mass of the loads only",tippingTorque:"Torque about the edge"},view:{stable:"Stable",tipping:"Tipping over",centre:"centre of mass",support:"support up to \xB1{half}",markersOption:"Centre of mass and plumb line"},graph:{angle:"Tilt of the board against time"},challenge:{offCentre:{title:"Off centre but stable",description:"Keep the board stable with its centre of mass at least 0.4 m from the middle.",hint:"Move one load outwards, but keep the centre of mass above the support."},tipOver:{title:"Tip it over",description:"Make the board tip over.",hint:"Move the centre of mass beyond the edge of the support: put the loads far out on one side."},unequal:{title:"Unequal but balanced",description:"With one load at least twice as heavy as the other, put the centre of mass exactly in the middle.",hint:"m\u2081\xB7x\u2081 = \u2212m\u2082\xB7x\u2082: the heavier load must sit closer to the middle."},edge:{title:"On the very edge",description:"Keep the board stable with its centre of mass less than 2 cm from the edge of the support.",hint:"Watch the distance to the edge and move a load in small steps."},boardHolds:{title:"The board holds it",description:"Make the loads alone overhang the support, yet keep the board stable.",hint:"A heavy board pulls the centre of mass back towards the middle."}}}},a={sim:s};export{a as default,s as sim};
